/** Время записи журнала: «היום · ЧЧ:ММ» (S-30 AC2). */
export const TODAY_TIME = /היום · \d{1,2}:\d{2}/;

/** Тексты записей «היסטוריית עסקה» сверху вниз (S-30 AC3: новые сверху). */
export async function historyEntries(page: Page): Promise<string[]> {
  await expect(page.getByText('היסטוריית עסקה')).toBeVisible();
  const body = await page.locator('body').innerText();
  const start = body.indexOf('היסטוריית עסקה');
  return body
    .slice(start + 'היסטוריית עסקה'.length)
    .split('\n')
    .map((s) => s.trim())
    .filter(Boolean);
}
